<div class="section-heading"><div><div class="eyebrow">Governança</div><h1>Documentos legais</h1><p class="text-secondary mb-0">Publique Termos de Uso e Política de Privacidade com versão e trilha de aceite.</p></div></div>
<div class="alert alert-warning"><strong>Revisão jurídica recomendada:</strong> o sistema entrega textos operacionais completos e versionamento, mas os dados da empresa e as condições comerciais devem ser conferidos por profissional jurídico antes do lançamento definitivo.</div>
<div class="card mb-4"><div class="card-header"><strong>Identificação da administradora</strong></div><div class="card-body"><form method="post" action="/master/documentos-legais/configuracoes" class="row g-3"><?=\App\Core\CSRF::field()?><div class="col-md-6"><label class="form-label">Razão social / nome jurídico</label><input class="form-control" name="legal_name" value="<?=htmlspecialchars($settings['legal_name'])?>"></div><div class="col-md-3"><label class="form-label">CNPJ/CPF</label><input class="form-control" name="document" value="<?=htmlspecialchars($settings['document'])?>"></div><div class="col-md-3"><label class="form-label">E-mail de suporte</label><input class="form-control" type="email" name="support_email" value="<?=htmlspecialchars($settings['support_email'])?>"></div><div class="col-md-4"><label class="form-label">E-mail de privacidade</label><input class="form-control" type="email" name="privacy_email" value="<?=htmlspecialchars($settings['privacy_email'])?>"></div><div class="col-md-5"><label class="form-label">Endereço da administradora</label><input class="form-control" name="address" value="<?=htmlspecialchars($settings['address'])?>"></div><div class="col-md-3"><label class="form-label">Foro</label><input class="form-control" name="foro" value="<?=htmlspecialchars($settings['foro'])?>" placeholder="Carpina/PE"></div><div class="col-12"><button class="btn btn-primary">Salvar identificação</button></div></form></div></div>
<div class="row g-4"><?php foreach(['terms'=>'Termos de Uso','privacy'=>'Política de Privacidade'] as $type=>$label):$items=array_values(array_filter($docs,fn($d)=>$d['type']===$type));$published=current(array_filter($items,fn($d)=>$d['status']==='published'))?:null;?><div class="col-lg-6"><div class="card h-100"><div class="card-header d-flex justify-content-between"><strong><?=$label?></strong><?php if($published):?><a target="_blank" href="<?=$type==='terms'?'/termos':'/privacidade'?>">Ver publicado</a><?php endif;?></div><div class="card-body"><?php if($published):?><div class="mb-3"><span class="badge text-bg-success">Publicado</span><strong class="ms-2">Versão <?=htmlspecialchars($published['version'])?></strong><div class="small text-secondary mt-1"><?=(int)$published['acceptances']?> aceite(s) registrado(s)</div></div><?php endif;?><form method="post" action="/master/documentos-legais/nova-versao" class="row g-2 mb-3"><?=\App\Core\CSRF::field()?><input type="hidden" name="type" value="<?=$type?>"><div class="col"><input class="form-control" name="version" placeholder="Nova versão, ex.: 1.1" required></div><div class="col-auto"><button class="btn btn-outline-primary">Criar versão</button></div></form><div class="list-group"><?php foreach($items as $d):?><a class="list-group-item list-group-item-action d-flex justify-content-between align-items-center" href="/master/documentos-legais/<?=(int)$d['id']?>/editar"><span>Versão <?=htmlspecialchars($d['version'])?></span><span class="badge <?=$d['status']==='published'?'text-bg-success':($d['status']==='draft'?'text-bg-warning':'text-bg-secondary')?>"><?=['published'=>'Publicado','draft'=>'Rascunho','archived'=>'Arquivado'][$d['status']]??$d['status']?></span></a><?php endforeach;?></div></div></div></div><?php endforeach;?></div>

<div class="card mt-4"><div class="card-header d-flex justify-content-between align-items-center"><strong>Últimos aceites registrados</strong><span class="badge text-bg-light">Auditoria</span></div><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Data</th><th>Usuário</th><th>Empresa</th><th>Documento</th><th>Versão</th><th>IP</th></tr></thead><tbody><?php foreach(($acceptances??[]) as $a):?><tr><td><?=date('d/m/Y H:i',strtotime($a['accepted_at']))?></td><td><strong><?=htmlspecialchars($a['user_name'])?></strong><div class="small text-secondary"><?=htmlspecialchars($a['email'])?></div></td><td><?=htmlspecialchars($a['tenant_name']??'—')?></td><td><?=$a['type']==='terms'?'Termos de Uso':'Política de Privacidade'?></td><td><?=htmlspecialchars($a['version'])?></td><td><?=htmlspecialchars($a['ip_address']??'—')?></td></tr><?php endforeach;?><?php if(empty($acceptances)):?><tr><td colspan="6"><div class="empty-state">Nenhum aceite registrado ainda.</div></td></tr><?php endif;?></tbody></table></div></div>
